import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as r,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Grok Connectors","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/grok/grok-connectors.md","filePath":"products/ai-coding/grok/grok-connectors.md","lastUpdated":1787042982000}'),a={name:"products/ai-coding/grok/grok-connectors.md"};function s(c,t,i,l,d,h){return r(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="grok-connectors" tabindex="-1">Grok Connectors <a class="header-anchor" href="#grok-connectors" aria-label="Permalink to &quot;Grok Connectors&quot;">​</a></h1><blockquote><p>Official definition (<a href="https://docs.x.ai/grok/connectors" target="_blank" rel="noreferrer">docs.x.ai/grok/connectors</a>): &quot;Connectors are available to all Grok users and let Grok access your external tools and data sources directly within a conversation. Search your email, browse files in cloud storage, check your calendar, and more without leaving the chat.&quot;</p><p>Analog: <a href="./../claude/connectors.html">Claude Connectors</a>. This page is the <strong>chat</strong> connector catalog. It is not Grok Build MCP (<code>grok mcp add</code>) and not Grok Bot plugins.</p></blockquote><h2 id="goals-and-non-goals" tabindex="-1">Goals and non-goals <a class="header-anchor" href="#goals-and-non-goals" aria-label="Permalink to &quot;Goals and non-goals&quot;">​</a></h2><p><strong>Audience:</strong> people who want Grok to read mail, Drive, calendar, or a custom MCP server <strong>inside grok.com chat</strong>.</p><p><strong>Goals:</strong> list the three official kinds, the built-in table, the Business admin gate, and the local-tunnel rule.</p><p><strong>Non-goals:</strong> a second MCP protocol tutorial, invented catalog entries, or Grok Build <code>[mcp_servers]</code> config (that is <a href="./grok-cli.html">grok-cli.md</a> / <a href="./grok-cookbook.html">cookbook</a>).</p><h2 id="three-kinds" tabindex="-1">Three kinds <a class="header-anchor" href="#three-kinds" aria-label="Permalink to &quot;Three kinds&quot;">​</a></h2><p><a href="https://docs.x.ai/grok/connectors" target="_blank" rel="noreferrer">connectors</a>:</p><table tabindex="0"><thead><tr><th>Kind</th><th>Who maintains it</th><th>How you add it</th></tr></thead><tbody><tr><td><strong>Built-in</strong></td><td>xAI, native OAuth</td><td><a href="https://grok.com/connectors" target="_blank" rel="noreferrer">grok.com/connectors</a> → <strong>New Connector</strong> → pick the service → OAuth</td></tr><tr><td><strong>Catalog</strong></td><td>Pre-configured OAuth for more third-party services</td><td>Same page; browse the catalog. Official docs do not freeze a full name list</td></tr><tr><td><strong>Custom MCP</strong></td><td>You (public MCP server)</td><td><strong>New Connector</strong> → <strong>Custom</strong> → MCP server URL + auth</td></tr></tbody></table><p>Once connected, Grok can use the connector&#39;s tools automatically when the question relates to that service. No extra per-chat toggle is documented on this page.</p><h3 id="built-in-connectors" tabindex="-1">Built-in connectors <a class="header-anchor" href="#built-in-connectors" aria-label="Permalink to &quot;Built-in connectors&quot;">​</a></h3><p>Official table (<a href="https://docs.x.ai/grok/connectors" target="_blank" rel="noreferrer">connectors</a>):</p><table tabindex="0"><thead><tr><th>Connector</th><th>What it connects</th></tr></thead><tbody><tr><td><strong>Gmail &amp; Google Calendar</strong></td><td>Gmail messages and Google Calendar events</td></tr><tr><td><strong>Google Drive</strong></td><td>Google Drive files, Docs, Sheets, and Slides</td></tr><tr><td><strong>OneDrive</strong></td><td>Microsoft OneDrive personal storage</td></tr><tr><td><strong>Outlook Mail &amp; Calendar</strong></td><td>Outlook email and calendar events</td></tr><tr><td><strong>Microsoft Teams</strong></td><td>Microsoft Teams messages, channels, and chats</td></tr><tr><td><strong>SharePoint</strong></td><td>Microsoft SharePoint sites and document libraries</td></tr><tr><td><strong>Salesforce</strong></td><td>Salesforce CRM — explore objects, query records, create and update</td></tr></tbody></table><h3 id="custom-mcp-connectors" tabindex="-1">Custom MCP connectors <a class="header-anchor" href="#custom-mcp-connectors" aria-label="Permalink to &quot;Custom MCP connectors&quot;">​</a></h3><p>Official capabilities (<a href="https://docs.x.ai/grok/connectors" target="_blank" rel="noreferrer">connectors</a>):</p><ul><li>Expose any internal API, database, or SaaS tool to Grok.</li><li>Define your own tools with custom schemas and logic.</li><li>Control authentication and access on your own infrastructure.</li></ul><p>The MCP server <strong>must be reachable over the public internet</strong>. <code>localhost</code> and RFC1918 addresses (<code>127.0.0.1</code>, <code>10.x</code>, <code>172.16.x</code>, <code>192.168.x</code>) are <strong>rejected</strong> (<a href="https://docs.x.ai/grok/connectors/custom-mcp-tunneling" target="_blank" rel="noreferrer">custom-mcp-tunneling</a>).</p><p>Tunnel pattern from that page:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Grok ──► https://your-tunnel.example.com ──► tunnel provider ──► localhost:3001</span></span></code></pre></div><p>Official examples: <strong>ngrok</strong> (<code>ngrok http 3001</code>) and <strong>Cloudflare Tunnel</strong> (<code>cloudflared tunnel --url http://localhost:3001</code>). Cloudflare <strong>quick</strong> tunnels do <strong>not</strong> support SSE — if your server uses SSE, use ngrok. Streamable HTTP is fine on Cloudflare.</p><p>Tunnels are temporary on free tiers. Restart → new URL → remove the old connector and add the new one. Keep the local server running; Grok calls it on demand.</p><h2 id="business-and-enterprise" tabindex="-1">Business and Enterprise <a class="header-anchor" href="#business-and-enterprise" aria-label="Permalink to &quot;Business and Enterprise&quot;">​</a></h2><p><a href="https://docs.x.ai/grok/connectors" target="_blank" rel="noreferrer">connectors</a>:</p><blockquote><p>For Grok Business and Enterprise users, a team admin must first provision a connector in the <a href="https://docs.x.ai/grok/connector-management" target="_blank" rel="noreferrer">cloud console</a> before it is available to members of the organization.</p></blockquote><p>Admin path (<a href="https://docs.x.ai/grok/connector-management" target="_blank" rel="noreferrer">connector-management</a>): <a href="https://console.x.ai" target="_blank" rel="noreferrer">console.x.ai</a> → team → <strong>Grok Business → Connectors</strong>. Adding/removing needs <strong>Team Read-Write</strong>.</p><ol><li><strong>+ Add Connector</strong> from the catalog, or <strong>Other</strong> + MCP URL.</li><li>Some Microsoft / Salesforce connectors need extra admin consent. The management page points at service-specific guides for SharePoint, OneDrive, and Salesforce.</li><li>After the admin provisions it, members still connect <strong>their own</strong> accounts on <a href="https://grok.com/connectors" target="_blank" rel="noreferrer">grok.com/connectors</a>.</li><li><strong>Remove</strong> deletes it for the team; indexed data associated with the connector may be removed.</li></ol><p>Personal (non-Business) accounts skip the admin step.</p><h2 id="not-these-connectors" tabindex="-1">Not these connectors <a class="header-anchor" href="#not-these-connectors" aria-label="Permalink to &quot;Not these connectors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Looks similar</th><th>Actually is</th></tr></thead><tbody><tr><td>Grok chat Connectors</td><td>This page</td></tr><tr><td>Grok Build MCP</td><td><code>grok mcp add</code> / <code>[mcp_servers]</code> in <code>~/.grok/config.toml</code> — tools namespaced <code>&lt;server&gt;__&lt;tool&gt;</code></td></tr><tr><td>Grok Bot &quot;Plugins&quot;</td><td><a href="./grok-bot.html">Grok Bot</a> Settings → Plugins; <code>@</code> to attach</td></tr><tr><td>Voice API <code>mcp</code> tool</td><td>Server-side MCP on <code>wss://api.x.ai/v1/realtime</code> (<a href="./grok-voice.html">Voice</a>)</td></tr></tbody></table><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><ul><li>Pointing a custom connector at <code>http://localhost:3001</code>. Officially rejected.</li><li>Expecting a Business member to see Gmail before an admin provisions it.</li><li>Copying Grok Build MCP config into grok.com. Different product, different host.</li><li>Using Cloudflare quick tunnels with an SSE MCP server.</li></ul><h2 id="official-docs" tabindex="-1">Official docs <a class="header-anchor" href="#official-docs" aria-label="Permalink to &quot;Official docs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Use</th></tr></thead><tbody><tr><td><a href="https://docs.x.ai/grok/connectors" target="_blank" rel="noreferrer">docs.x.ai/grok/connectors</a></td><td>Three kinds + built-in table</td></tr><tr><td><a href="https://docs.x.ai/grok/connector-management" target="_blank" rel="noreferrer">docs.x.ai/grok/connector-management</a></td><td>Business admin provision</td></tr><tr><td><a href="https://docs.x.ai/grok/connectors/custom-mcp-tunneling" target="_blank" rel="noreferrer">docs.x.ai/grok/connectors/custom-mcp-tunneling</a></td><td>Public URL / tunnels</td></tr><tr><td><a href="https://grok.com/connectors" target="_blank" rel="noreferrer">grok.com/connectors</a></td><td>User-facing add/connect UI</td></tr><tr><td><a href="https://docs.x.ai/grok/overview" target="_blank" rel="noreferrer">docs.x.ai/grok/overview</a></td><td>Connectors as a chat capability</td></tr></tbody></table><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./grok-chat.html">Grok Chat</a></li><li><a href="./grok-business.html">Grok Business</a> — admin must provision first</li><li><a href="./grok-cookbook.html">Grok Build cookbook</a> — CLI MCP, not this</li><li><a href="./grok-bot.html">Grok Bot</a></li><li><a href="./">Grok learning map</a></li></ul>',35)])])}const k=e(a,[["render",s]]);export{f as __pageData,k as default};
